57	// RunMCPServer runs the Model Context Protocol stdio server for an OKF bundle.
58	func RunMCPServer(bundleDir string) error {
59		return RunMCPServerIO(bundleDir, os.Stdin, os.Stdout)
60	}
61	
62	const maxMCPLineLength = 4 * 1024 * 1024 // 4MB maximum JSON-RPC message size
63	
64	func readBoundedLine(r *bufio.Reader, maxLen int) ([]byte, bool, error) {
65		var line []byte
66		for {
67			chunk, isPrefix, err := r.ReadLine()
68			if err != nil {
69				if err == io.EOF && len(line) > 0 {
70					return line, false, nil
71				}
72				return nil, false, err
73			}
74			line = append(line, chunk...)
75			if len(line) > maxLen {
76				for isPrefix && err == nil {
77					_, isPrefix, err = r.ReadLine()
78				}
79				return nil, true, nil
80			}
81			if !isPrefix {
82				break
83			}
84		}
85		return line, false, nil
86	}
