205	func (s *mcpServer) handleRequest(req jsonRPCRequest) {
206		isNotification := req.ID == nil || string(*req.ID) == "null"
207	
208		switch req.Method {
209		case "initialize":
210			s.sendResponse(req.ID, map[string]any{
211				"protocolVersion": "2024-11-05",
212				"serverInfo": map[string]string{
213					"name":    "okf-agent-memory",
214					"version": MCPVersion,
215				},
216				"capabilities": map[string]any{
217					"tools": map[string]bool{
218						"listChanged": false,
219					},
220					"resources": map[string]bool{
221						"listChanged": false,
222					},
223					"prompts": map[string]bool{
224						"listChanged": false,
225					},
226				},
227			})
228	
229		case "notifications/initialized", "initialized":
230			// Standard lifecycle notification after initialize handshake; no response.
231			return
232	
233		case "notifications/cancelled", "cancelled":
234			// Notification indicating client canceled a request; no response.
235			return
236	
237		case "ping":
238			s.sendResponse(req.ID, map[string]any{})
239	
240		case "resources/list":
241			s.sendResponse(req.ID, map[string]any{
242				"resources": []any{},
243			})
244	
245		case "prompts/list":
246			s.sendResponse(req.ID, map[string]any{
247				"prompts": []any{},
248			})
249	
250		case "tools/list":
251			s.sendResponse(req.ID, map[string]any{
252				"tools": GetMCPTools(),
253			})
254	
255		case "tools/call":
256			s.handleToolCall(req)
257	
258		default:
259			if isNotification || strings.HasPrefix(req.Method, "notifications/") {
260				// Per JSON-RPC 2.0 & MCP, ignore unknown notifications silently
261				return
262			}
263			s.sendError(req.ID, -32601, "Method not found")
264		}
265	}
