30	// atomicWriteFile writes data to a temporary file in the same directory as targetPath,
31	// flushes it to disk, and atomically replaces targetPath using os.Rename.
32	func atomicWriteFile(targetPath string, data []byte, perm os.FileMode) error {
33		dir := filepath.Dir(targetPath)
34		if err := os.MkdirAll(dir, 0o755); err != nil {
35			return fmt.Errorf("failed to create directory for %s: %w", targetPath, err)
36		}
37	
38		tmpFile, err := os.CreateTemp(dir, ".tmp-okf-*")
39		if err != nil {
40			return fmt.Errorf("failed to create temporary file: %w", err)
41		}
42		tmpPath := tmpFile.Name()
43		defer func() {
44			_ = os.Remove(tmpPath)
45		}()
46	
47		if _, err := tmpFile.Write(data); err != nil {
48			_ = tmpFile.Close()
49			return fmt.Errorf("failed to write to temporary file: %w", err)
50		}
51		if err := tmpFile.Sync(); err != nil {
52			_ = tmpFile.Close()
53			return fmt.Errorf("failed to sync temporary file: %w", err)
54		}
55		if err := tmpFile.Close(); err != nil {
56			return fmt.Errorf("failed to close temporary file: %w", err)
57		}
58		if err := os.Chmod(tmpPath, perm); err != nil {
59			return fmt.Errorf("failed to set permissions on temporary file: %w", err)
60		}
61		if err := os.Rename(tmpPath, targetPath); err != nil {
62			return fmt.Errorf("failed to atomically replace %s: %w", targetPath, err)
63		}
64		return nil
65	}
