67	// InitBundle initializes a new OKF v0.2 bundle with root index.md and log.md.
68	func InitBundle(dir string) error {
69		if err := os.MkdirAll(dir, 0o755); err != nil {
70			return fmt.Errorf("failed to create directory: %w", err)
71		}
72	
73		return WithBundleLock(dir, func() error {
74			rootIndex := filepath.Join(dir, "index.md")
75			if _, err := os.Stat(rootIndex); os.IsNotExist(err) {
76				indexContent := "---\nokf_version: \"0.2\"\n---\n\n# Knowledge Base\n\n"
77				if err := atomicWriteFile(rootIndex, []byte(indexContent), 0o644); err != nil {
78					return fmt.Errorf("failed to write root index.md: %w", err)
79				}
80			}
81	
82			logFile := filepath.Join(dir, "log.md")
83			if _, err := os.Stat(logFile); os.IsNotExist(err) {
84				today := time.Now().UTC().Format("2006-01-02")
85				logContent := fmt.Sprintf("## %s\n* **Creation**: Initialized OKF v0.2 knowledge bundle.\n", today)
86				if err := atomicWriteFile(logFile, []byte(logContent), 0o644); err != nil {
87					return fmt.Errorf("failed to write log.md: %w", err)
88				}
89			}
90	
91			return nil
92		})
93	}
