95	// AppendLogEntry prepends a new dated change entry to log.md.
96	func AppendLogEntry(bundleDir, entryType, description string) error {
97		logPath := filepath.Join(bundleDir, "log.md")
98		if _, err := ensureWithinRoot(bundleDir, logPath); err != nil {
