252	func updateParentIndexLocked(bundleDir string, c *Concept) error {
253		absBundle, err := filepath.Abs(bundleDir)
254		if err != nil {
255			return fmt.Errorf("invalid bundle directory: %w", err)
256		}
257	
258		normConceptPath := strings.ReplaceAll(c.Path, "\\", "/")
259		dir := path.Dir(normConceptPath)
260		indexRelPath := "index.md"
261		if dir != "." {
262			indexRelPath = filepath.Join(filepath.FromSlash(dir), "index.md")
263		}
264	
265		indexPath := filepath.Join(absBundle, filepath.Clean(indexRelPath))
266		rel, err := filepath.Rel(absBundle, indexPath)
267		relSlash := strings.ReplaceAll(rel, "\\", "/")
268		if err != nil || relSlash == ".." || strings.HasPrefix(relSlash, "../") {
269			return fmt.Errorf("path traversal denied: parent index %q escapes bundle directory", indexRelPath)
270		}
271		if _, err := ensureWithinRoot(bundleDir, indexPath); err != nil {
272			return err
273		}
274	
275		if err := os.MkdirAll(filepath.Dir(indexPath), 0o755); err != nil {
276			return fmt.Errorf("failed to create directory for parent index %q: %w", indexRelPath, err)
277		}
278	
279		targetFilename := filepath.Base(c.Path)
280		targetTitle := strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(c.Title, "\r", " "), "\n", " "))
281		if targetTitle == "" {
282			targetTitle = targetFilename
283		}
284		targetDesc := strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(c.Description, "\r", " "), "\n", " "))
285	
286		newListing := fmt.Sprintf("* [%s](%s) - %s", targetTitle, targetFilename, targetDesc)
287		if targetDesc == "" {
288			newListing = fmt.Sprintf("* [%s](%s)", targetTitle, targetFilename)
289		}
290	
291		existingContent := ""
292		// #nosec G304 -- indexPath is validated within bundleDir via ensureWithinRoot
293		if data, err := os.ReadFile(indexPath); err == nil {
294			existingContent = string(data)
295		} else {
296			// Create index.md with default header
297			header := fmt.Sprintf("# %s\n\n", titleCase(filepath.Base(dir)))
298			if dir == "." {
299				header = "---\nokf_version: \"0.2\"\n---\n\n# Knowledge Base\n\n"
300			}
301			existingContent = header
302		}
303	
304		// Check if already listed
305		linkTarget := fmt.Sprintf("(%s)", targetFilename)
306		if strings.Contains(existingContent, linkTarget) {
307			// Update existing line
308			lines := strings.Split(existingContent, "\n")
309			for i, l := range lines {
310				if strings.Contains(l, linkTarget) {
311					lines[i] = newListing
312					break
313				}
314			}
315			existingContent = strings.Join(lines, "\n")
316		} else {
317			// Append listing
318			existingContent = strings.TrimRight(existingContent, "\n") + "\n" + newListing + "\n"
319		}
320	
321		// #nosec G703 -- indexPath is verified within bundleDir
322		return atomicWriteFile(indexPath, []byte(existingContent), 0o644)
323	}
