58	// ensureWithinRoot verifies that targetPath (resolving all symlinks) stays strictly
59	// within the canonical root directory. It returns the resolved absolute path or an error.
60	func ensureWithinRoot(rootDir, targetPath string) (string, error) {
61		// Absolutise BEFORE resolving symlinks. EvalSymlinks on a relative path returns a
62		// relative path, so a relative root under a symlinked cwd (macOS /tmp -> /private/tmp)
63		// stayed unresolved while the target was resolved, and every legitimate write looked
64		// like an escape.
65		absRoot, err := filepath.Abs(rootDir)
66		if err != nil {
67			return "", fmt.Errorf("failed to get absolute path of bundle root: %w", err)
68		}
69		realRoot, err := filepath.EvalSymlinks(absRoot)
70		if err != nil {
71			return "", fmt.Errorf("failed to resolve bundle root: %w", err)
72		}
73	
74		cleanTarget := strings.ReplaceAll(targetPath, "\\", "/")
75		if IsAbsPath(targetPath) {
76			cleanTarget = filepath.Clean(cleanTarget)
77		} else {
78			cleanTarget = path.Join(filepath.ToSlash(realRoot), cleanTarget)
79		}
80	
81		absTarget, err := filepath.Abs(filepath.FromSlash(cleanTarget))
82		if err != nil {
83			return "", err
84		}
85	
86		// Walk up to find the closest ancestor that exists, and evaluate its symlinks
87		curr := absTarget
88		var missingParts []string
89		for {
90			_, lstatErr := os.Lstat(curr)
91			if lstatErr == nil {
92				break
93			}
94			missingParts = append([]string{filepath.Base(curr)}, missingParts...)
95			parent := filepath.Dir(curr)
96			if parent == curr {
97				break
98			}
99			curr = parent
100		}
101	
102		realCurr, err := filepath.EvalSymlinks(curr)
103		if err != nil {
104			return "", fmt.Errorf("failed to resolve path %q: %w", curr, err)
105		}
106		realCurr, err = filepath.Abs(realCurr)
107		if err != nil {
108			return "", err
109		}
110	
111		parts := append([]string{realCurr}, missingParts...)
112		realTarget := filepath.Join(parts...)
113	
114		rel, err := filepath.Rel(realRoot, realTarget)

